import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cumprod_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void cumprod_kernel(const float* __restrict__ in, float* __restrict__ out, int rows, int cols) {
    int row = blockIdx.x;
    if (row < rows) {
        float cumulative = 1.0f;
        int offset = row * cols;
        for (int i = 0; i < cols; i++) {
            cumulative *= in[offset + i];
            out[offset + i] = cumulative;
        }
    }
}

torch::Tensor cumprod_cuda(torch::Tensor x, int dim) {
    // This example only handles 2D tensors with dim=1.
    TORCH_CHECK(x.dim() == 2, "Only 2D tensors are supported in this example.");
    TORCH_CHECK(dim == 1, "This example only supports cumulative product along dimension 1.");

    int rows = x.size(0);
    int cols = x.size(1);

    auto out = torch::zeros_like(x);

    cumprod_kernel<<<rows, 1>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        rows,
        cols
    );

    return out;
}
"""

cumprod_cpp_source = "torch::Tensor cumprod_cuda(torch::Tensor x, int dim);"

cumprod_op = load_inline(
    name="cumprod_op",
    cpp_sources=cumprod_cpp_source,
    cuda_sources=cumprod_source,
    functions=["cumprod_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    def __init__(self, dim):
        super().__init__()
        self.dim = dim

    def forward(self, x):
        return cumprod_op.cumprod_cuda(x, self.dim)

